#[test]
fn abi() {
    if !std::arch::is_x86_feature_detected!("avx2") {
        return;
    }
    crate::low::abi::call!(
        mldsa_decompose_32,
        &mut crate::low::abi::Aligned([0; 256]).0,
        &mut crate::low::abi::Aligned([0; 256]).0
    );
}
